+                      OnTaskAdded="HandleTaskAdded" />
+
+        <KanbanColumn Title="Done"
+                      Status="Done"
+                      Tasks="GetFilteredTasks("Done")"
+                      ShowMoveLeft="true"
+                      ShowMoveRight="false"
+                      OnMoveLeft="id => MoveTask(id, "In Progress")"
+                      OnTaskAdded="HandleTaskAdded" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> tasks = new();
+    private string searchText = string.Empty;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        var filtered = tasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchText))
+        {
+            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
+        }
+        return filtered.ToList();
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = tasks.FirstOrDefault(t => t.Id == taskId);
+            if (task is not null)
+            {
+                tasks = tasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task HandleTaskAdded((string Title, string Assignee, string Priority, DateTime DueDate) newTask)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTask.Title, newTask.Assignee, newTask.Priority, newTask.DueDate);
+            tasks.Add(created);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
